import string

def encode_cyclic(s: str) -> str:
    """
    Returns encoded string by cycling groups of three characters.
    """
    # Split the string into groups of up to 3 characters
    groups = [s[(i * 3): min((i + 1) * 3, len(s))] for i in range((len(s) + 2) // 3)]
    # For each group of 3, rotate right by 1 (move last char to front)
    shifted = []
    for group in groups:
        if len(group) == 3:
            shifted.append(group[1:] + group[0])
        else:
            shifted.append(group)  # shorter groups are unchanged
    return ''.join(shifted)

def decode_cyclic(s: str) -> str:
    """
    Decodes a string that was encoded with encode_cyclic.
    Reverses the right-rotate-by-one on every full 3-character group.
    """
    groups = [s[(i * 3): min((i + 1) * 3, len(s))] for i in range((len(s) + 2) // 3)]
    decoded = []
    for group in groups:
        if len(group) == 3:
            # To reverse a right rotate by 1, rotate left by 1 (move first char to end)
            decoded.append(group[1:] + group[0])
        else:
            decoded.append(group)
    return ''.join(decoded)
