import string

def encode_shift(s: str) -> str:
    """
    Returns encoded string by shifting every alphabetical character by 5 positions.
    Non-alphabet characters are left unchanged.
    """
    res = []
    for ch in s:
        if ch.isalpha():
            base = ord('a') if ch.islower() else ord('A')
            shifted = (ord(ch) - base + 5) % 26 + base
            res.append(chr(shifted))
        else:
            res.append(ch)
    return "".join(res)

def decode_shift(s: str) -> str:
    """
    Decodes a string that was encoded with encode_shift by shifting each
    alphabetical character back by 5 positions.
    """
    res = []
    for ch in s:
        if ch.isalpha():
            base = ord('a') if ch.islower() else ord('A')
            shifted = (ord(ch) - base - 5) % 26 + base
            res.append(chr(shifted))
        else:
            res.append(ch)
    return "".join(res)
