import string

def hex_key(num: str) -> int:
    """Counts prime-valued hexadecimal digits in the input string."""
    # Prime hexadecimal digits (by their hex value): 2, 3, 5, 7, B (11), D (13)
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    count = 0
    for ch in num.upper():
        if ch in prime_hex_digits:
            count += 1
    return count
