def encrypt(s):
    """
    Rotate the alphabet by 4 positions forward (since 2 places multiplied by 2).
    Non-alphabetic characters are left unchanged.
    """
    import string
    shift = 4  # 2 * 2
    alphabet = string.ascii_lowercase
    rot = {ch: alphabet[(i + shift) % 26] for i, ch in enumerate(alphabet)}
    # Handle uppercase as well, but only if present in input
    upper_rot = {ch: alphabet[(i + shift) % 26].upper() for i, ch in enumerate(alphabet)}
    res = []
    for c in s:
        if c.islower():
            res.append(rot.get(c, c))
        elif c.isupper():
            res.append(upper_rot.get(c, c))
        else:
            res.append(c)
    return ''.join(res)

