def compare_one(a, b):
    """
    Compare two values (int, float, or string representing a number) and return the larger one
    in its original type. Return None if they are equal.
    """
    # Helper to convert string numbers (with commas as thousand separators) to float
    def to_number(x):
        try:
            if isinstance(x, str):
                # Replace comma with dot to handle decimal numbers written as "1,2"
                x = x.replace(',', '.')
                return float(x)
            else:
                return float(x)
        except ValueError:
            # If conversion fails (invalid input), just return original (will compare as their types)
            return x

    num_a = to_number(a)
    num_b = to_number(b)

    # Compare based on the numeric value
    if num_a > num_b:
        # Return original type of a
        if isinstance(a, str):
            return a
        return a
    elif num_b > num_a:
        # Return original type of b
        if isinstance(b, str):
            return b
        return b
    else:
        # Equal numeric value, return None
        return None
